    ts_pop_txt: "Le texte est trop petit ? Vous pouvez l'agrandir.",
    ts_pop_hint: "Vous pouvez rouvrir ce panneau \u00e0 tout moment depuis le bouton dans l'en-t\u00eate ci-dessus.",
    ts_hc: "Contraste",
    ts_hc_0: "Contraste normal",
