    /* Ricerca sito */
    srch_ph: "Rechercher produits, codes de pi\u00e8ces, pages",
    srch_quick: "Aller \u00e0",
    srch_foot: "Fl\u00e8ches pour naviguer, Entr\u00e9e pour ouvrir",
    srch_g_prod: "Produits",
    srch_g_cat: "Cat\u00e9gories",
    srch_g_part: "Pi\u00e8ces d\u00e9tach\u00e9es",
